/**
 * Regenerates `src/data/sectionsForStates.ts` from `data/sections-for-states.json`,
 * and `src/data/sectionPoints.ts` from `data/section-points.json`.
 *
 * Run with `npm run generate` after editing either JSON source.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..')

const table = JSON.parse(fs.readFileSync(path.join(root, 'data/sections-for-states.json'), 'utf8'))

const source = [
  "import { SectionsForState } from '../types.js'",
  '',
  '// Generated by scripts/generate.ts from data/sections-for-states.json — do not edit by hand.',
  `export const SECTIONS_FOR_STATES: Record<string, SectionsForState> = ${JSON.stringify(table)}`,
  ''
].join('\n')

fs.writeFileSync(path.join(root, 'src/data/sectionsForStates.ts'), source)
console.log(`Wrote ${Object.keys(table).length} states and provinces`)

const points = Object.fromEntries(
  Object.entries(JSON.parse(fs.readFileSync(path.join(root, 'data/section-points.json'), 'utf8')) as Record<string, { lat: number, lon: number }>)
    .map(([code, { lat, lon }]) => [code, { lat, lon }])
)

const pointsSource = [
  '// Generated by scripts/generate.ts from data/section-points.json — do not edit by hand.',
  '// The points themselves come from scripts/generate-points.ts; see data/NOTES.md.',
  `export const SECTION_POINTS: Record<string, { lat: number, lon: number }> = ${JSON.stringify(points)}`,
  ''
].join('\n')

fs.writeFileSync(path.join(root, 'src/data/sectionPoints.ts'), pointsSource)
console.log(`Wrote ${Object.keys(points).length} section points`)
